sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') return;

    var serviceType = g_form.getValue('service_type');
    var ga = new GlideAjax('x_2220337_vehicl_0.VehicleUtilsAjax');
    ga.addParam('sysparm_name', 'getAvailableMechanics');
    ga.addParam('sysparm_service_type', serviceType);
    ga.getXMLAnswer(function(answer) {
        try {
            var mechanics = JSON.parse(answer);
            var maxJobs = 3;
            for (var i = 0; i < mechanics.length; i++) {
                if (mechanics[i].sys_id === newValue) {
                    var currentJobs = parseInt(mechanics[i].current_jobs, 10) || 0;
                    if (currentJobs >= 2) {
                        g_form.addInfoMessage(
                            mechanics[i].name + ' currently has ' + currentJobs +
                            ' of ' + maxJobs + ' maximum jobs assigned. Consider selecting another mechanic.'
                        );
                    }
                    break;
                }
            }
        } catch (e) {
            // Silently handle parse errors
        }
    });
}
